@IsTest
private class NewsFeedClassTest {
   @IsTest
   static void testGetNewsFeedCount() {
      ConnectApi.FeedElementPage testPage = new ConnectApi.FeedElementPage();
      testPage.elements = new List<ConnectApi.FeedItem>();
      ConnectApi.ChatterFeeds.setTestGetFeedElementsFromFeed(null, ConnectApi.FeedType.News, 'me', testPage);
      Assert.areEqual(0, NewsFeedClass.getNewsFeedCount(), 'feed count');
   }
}


